class WorkflowDefinition(TypedDict):
    """
    Reacts to a conversation with messages, questions, decisions, waits and assignments.
    """

    trigger: Literal["conversation_opened", "first_message_received", "message_received", "message_sent", "conversation_inactive", "team_message_unanswered", "schedule", "conversation_assigned", "call_received"]
    """
    The event that starts the workflow; `condition` decides whether that occurrence runs it. `conversation_opened` runs when a conversation opens; `first_message_received` when the contact writes first in a conversation, before any message from the business; `message_received` on every incoming message; `message_sent` within 15 minutes of an outgoing message, unless the contact replied first; `conversation_inactive` and `team_message_unanswered` after `inactivity_seconds`. `schedule` runs at each of its `schedule.times` on each conversation assigned then to a member its `condition` names with `assignee` `is`, which it requires. `conversation_assigned` runs when a conversation is assigned to a member; the assignment an AI handoff makes does not run it. Both take only `turn_on_ai`, `turn_off_ai`, `decision` and `end` steps, and only they take `turn_on_ai` and `turn_off_ai`. `call_received` decides who answers a WhatsApp call on the WhatsApp numbers with AI calls on that its `condition` names: its flow takes only `answer_call`, `decline_call` and `decision`s on `channel` and `time`, and the first active one that reaches a call step, in most recently published order, decides, over whoever holds the conversation.
    """
    condition: Optional[Condition]
    """
    Whether an occurrence of the trigger runs the workflow; null runs every occurrence on every channel.
    """
    schedule: NotRequired[WorkflowDefinitionSchedule]
    """
    When a `schedule` workflow runs; required for it and only for it.
    """
    inactivity_seconds: NotRequired[int]
    """
    Seconds without activity before starting the flow: since the last team reply for team_message_unanswered, or the last message or reaction from either side for conversation_inactive.
    """
    flow: WorkflowDefinitionFlow
    """
    The steps and how they connect.
    """


class Workflow(TypedDict):
    """
    An automation Ricky runs for the organization.
    """

    id: str
    """
    Workflow ID.
    """
    name: str
    """
    Display name.
    """
    status: Literal["draft", "active", "paused"]
    """
    `draft` until activated; `paused` runs nothing new; `active` runs.
    """
    type: Literal["conversation", "scheduled"]
    """
    Which `definition` it has: a conversation flow or a daily template.
    """
    definition: Union[WorkflowDefinition, WorkflowDefinition1]
    updated_at: str
    """
    Last change to the workflow.
    """


